SELECT     CASE         WHEN m.name = 'resource' AND f.filename LIKE '%.mp4' THEN 'Vídeos (Recursos)'         WHEN m.name = 'resource' AND f.filename LIKE '%.mp3' THEN 'Podcasts (Recursos)'         WHEN m.name = 'resource' AND f.filename LIKE '%.pdf' THEN 'E-books (Recursos)'         WHEN m.name = 'resource' AND f.filename LIKE '%.epub' THEN 'Audiobooks (Recursos)'         WHEN m.name = 'resource' AND (f.filename LIKE '%.png' OR f.filename LIKE '%.jpg') THEN 'Infográficos (Recursos)'         WHEN m.name = 'resource' THEN 'Outros Recursos Digitais'         WHEN m.name = 'assign' THEN 'Atividades (Tarefa)'         WHEN m.name = 'quiz' THEN 'Atividades (Questionário)'         WHEN m.name = 'forum' THEN 'Atividades (Fórum)'         WHEN m.name = 'lesson' THEN 'Atividades (Lição)'         WHEN m.name = 'workshop' THEN 'Atividades (Oficina)'         WHEN m.name = 'choice' THEN 'Atividades (Escolha)'         WHEN m.name = 'feedback' THEN 'Atividades (Feedback)'         WHEN m.name = 'scorm' THEN 'Atividades (SCORM)'         WHEN m.name = 'chat' THEN 'Atividades (Chat)'         WHEN m.name = 'glossary' THEN 'Atividades (Glossário)'         WHEN m.name = 'wiki' THEN 'Atividades (Wiki)'         WHEN m.name = 'survey' THEN 'Atividades (Pesquisa)'         WHEN m.name = 'database' THEN 'Atividades (Base de Dados)'         WHEN m.name = 'book' THEN 'Recursos (Livro)'         WHEN m.name = 'page' THEN 'Recursos (Página)'         WHEN m.name = 'url' THEN 'Recursos (Link Externo)'         WHEN m.name = 'folder' THEN 'Recursos (Pasta)'         WHEN m.name = 'label' THEN 'Recursos (Rótulo)'         WHEN m.name = 'attendance' THEN 'Atividades (Presença)'         WHEN m.name = 'lti' THEN 'Atividades (Ferramenta Externa)'         ELSE 'Outras Atividades'     END AS tipo,     COUNT(cm.id) AS quantidade FROM     mdl_course_modules cm JOIN     mdl_modules m ON cm.module = m.id LEFT JOIN     mdl_resource r ON cm.instance = r.id AND m.name = 'resource' LEFT JOIN     mdl_files f ON f.itemid = r.id AND f.filearea = 'content' WHERE     (f.filename NOT LIKE '.%' OR f.filename IS NULL) GROUP BY     tipo ORDER BY     quantidade DESC;
